  gap: 24px;
}

.benefit-card {
  text-align: center;
  padding: 32px 24px;
  border-radius: var(--radius-lg);
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  transition: all var(--transition);
}

.benefit-card:hover {
  border-color: rgba(0,180,216,0.2);
  transform: translateY(-4px);
